if (!_hg || !_zc || !_ml) throw new Error("data/canon.js must load before ot-35-hag-mal.js");
(_hg.chapters = _hg.chapters || []).push(
  { n:1, summary:"The word of the Lord comes through Haggai in Darius's second year to governor Zerubbabel and high priest Joshua. The people excuse themselves: the time for rebuilding the Lord's house has not come, yet they live in finished, ceiled houses while the temple lies in waste. Twice the Lord says, Consider your ways: they sow much and reap little, eat and drink without enough, and earn wages that vanish as if into a bag with holes. He names the cause — heaven withheld its dew, the earth its fruit, and drought struck every field and labor — because His house lies waste while everyone runs to his own house. Haggai commands them to bring wood and build, promising the Lord will take pleasure in it and be glorified. Zerubbabel, Joshua, and the remnant obey and fear before the Lord; the Lord promises I am with you, stirs their spirits, and by the twenty-fourth day of the same month they are at work in the house of the Lord.",
    context:"Given on the first day of the sixth month in the second year of Darius, when the returned exiles under Zerubbabel and Joshua had let the temple work stand idle.",
    keyVerses:[
      { ref:"Haggai 1:5", text:"Now therefore thus saith the LORD of hosts; Consider your ways." },
      { ref:"Haggai 1:8", text:"Go up to the mountain, and bring wood, and build the house; and I will take pleasure in it, and I will be glorified, saith the LORD." },
      { ref:"Haggai 1:9", text:"Ye looked for much, and, lo, it came to little; and when ye brought it home, I did blow upon it. Why? saith the LORD of hosts. Because of mine house that is waste, and ye run every man unto his own house." }
    ],
    takeaway:"When God's house waits while we furnish our own, even our earnings leak away; put Him first and He says, I am with you.",
    quiz:[
      { q:"What excuse did the people give for not rebuilding the Lord's house?", choices:["The time is not come","The Persian king forbade it","The site lacked building stone","They were waiting for more silver"], a:0, why:"The people said the time had not come for the Lord's house to be built, while they dwelt in their own ceiled houses." },
      { q:"What picture did the Lord use for wages that never last?", choices:["Chaff the wind scatters","A bag with holes","A broken cistern","A moth-eaten coat"], a:1, why:"Haggai said he that earneth wages earneth wages to put it into a bag with holes — income that disappears before it does any good." },
      { q:"What does this chapter teach about putting off the Lord's work?", choices:["God accepts worship however late it comes","Delayed obedience is still full obedience","Neglecting God's priorities empties our own efforts, while putting Him first brings His presence","Temples matter more than any other commandment"], a:2, why:"Because the Lord's house lay waste, He blew on their harvests; once they obeyed, His message was I am with you." }
    ] },
  { n:2, summary:"Haggai speaks again in the seventh month, when elders who saw Solomon's temple count the new foundation as nothing beside it. The Lord answers: be strong, Zerubbabel, Joshua, and all the people, and work, for I am with you; His spirit remains among them according to the word covenanted when they came out of Egypt. He will shake the heavens, the earth, the sea, and all nations until the desire of all nations comes and He fills the house with glory — the latter house greater than the former, with peace in that place, for the silver and gold are His. A second word on the twenty-fourth of the ninth month asks the priests to rule: holiness does not spread by touch, but uncleanness does — so the people's work and offerings were unclean, and blasting, mildew, and hail had eaten their labor. Yet from the day the foundation is laid God promises blessing, and He will shake the kingdoms until Zerubbabel, His chosen servant, stands as a signet.",
    context:"Delivered in Darius's second year — the twenty-first day of the seventh month and again the twenty-fourth of the ninth — as Zerubbabel and Joshua led the rebuild.",
    keyVerses:[
      { ref:"Haggai 2:4", text:"Yet now be strong, O Zerubbabel, saith the LORD; and be strong, O Joshua, son of Josedech, the high priest; and be strong, all ye people of the land, saith the LORD, and work: for I am with you, saith the LORD of hosts:" },
      { ref:"Haggai 2:9", text:"The glory of this latter house shall be greater than of the former, saith the LORD of hosts: and in this place will I give peace, saith the LORD of hosts." },
      { ref:"Haggai 2:23", text:"In that day, saith the LORD of hosts, will I take thee, O Zerubbabel, my servant, the son of Shealtiel, saith the LORD, and will make thee as a signet: for I have chosen thee, saith the LORD of hosts." }
    ],
    takeaway:"God does not compare sizes; with His presence and promised glory, even a modest rebuild can outshine the first.",
    quiz:[
      { q:"Whom did the Lord tell to be strong and work?", choices:["Only the priests","Only the prophets","The Persian governors","Zerubbabel, Joshua, and all the people of the land"], a:3, why:"The Lord said three times to be strong — to Zerubbabel, to Joshua, and to all the people of the land — and to work, for He was with them." },
      { q:"What did the priests' ruling about holy flesh and uncleanness show?", choices:["Uncleanness spreads more easily than holiness","Sacrifices must be cooked before eating","Unclean people could not enter the temple at all","Holiness spreads to everything a priest touches"], a:0, why:"Holy flesh in a garment skirt made nothing else holy, but one unclean by a dead body defiled whatever he touched — so the people's works and offerings were unclean." },
      { q:"What did the Lord promise about the two houses?", choices:["The second temple would be destroyed like the first","The glory of the latter house would be greater than the former","The nations would finish the building for them","The new house would be larger in every measurement"], a:1, why:"He promised to fill this house with glory: the latter house's glory would exceed the former's, and He would give peace in that place." }
    ] }
);
(_zc.chapters = _zc.chapters || []).push(
  { n:1, summary:"Zechariah opens with the Lord's standing plea through the former prophets — turn ye unto me, and I will turn unto you — a plea the fathers ignored until the words took hold of them, as their own children now admit. Then the night visions begin. A man rides a red horse among myrtle trees in a hollow, with red, speckled, and white horses behind him; the angel explains they are those the Lord sent to walk to and fro through the earth, and they report that all the earth sits still and is at rest. The angel of the Lord pleads for Jerusalem after seventy years of indignation, and the Lord answers with good and comfortable words: He is jealous for Jerusalem and Zion, displeased with the nations at ease who worsened Judah's affliction, and returned with mercies — His house will be built and a line stretched over the city. Two linked visions follow: four horns that scattered Judah, and four carpenters coming to fray and cast out those horns.",
    context:"Set in Darius's second year — the call to return in the eighth month, the visions beginning the twenty-fourth day of the eleventh month, Sebat — while the temple work continued.",
    keyVerses:[
      { ref:"Zechariah 1:3", text:"Therefore say thou unto them, Thus saith the LORD of hosts; Turn ye unto me, saith the LORD of hosts, and I will turn unto you, saith the LORD of hosts." },
      { ref:"Zechariah 1:14", text:"So the angel that communed with me said unto me, Cry thou, saying, Thus saith the LORD of hosts; I am jealous for Jerusalem and for Zion with a great jealousy." },
      { ref:"Zechariah 1:16", text:"Therefore thus saith the LORD; I am returned to Jerusalem with mercies: my house shall be built in it, saith the LORD of hosts, and a line shall be stretched forth upon Jerusalem." }
    ],
    takeaway:"Return is always open: the Lord turns to whoever turns to Him, and mercy rebuilds what judgment tore down.",
    quiz:[
      { q:"What did the horses' report reveal about the world's condition?", choices:["The nations were arming for war against Judah","Famine had spread through every land","The whole earth sat still and was at rest","Judah's cities were already rebuilt"], a:2, why:"The riders told the angel of the Lord that all the earth sitteth still and is at rest, while Jerusalem had borne seventy years of indignation." },
      { q:"What was the work of the four carpenters in the second vision?", choices:["To rebuild the temple walls","To measure Jerusalem's gates","To restore the myrtle grove","To fray and cast out the horns that scattered Judah"], a:3, why:"The four horns had scattered Judah so no man lifted up his head; the four carpenters came to cast out those horns of the Gentiles." },
      { q:"Where did the rider on the red horse stand?", choices:["Among the myrtle trees","On the temple steps","Between two mountains of brass","Beside a river of living water"], a:0, why:"Zechariah saw a man riding a red horse standing among the myrtle trees in the bottom, with other horses behind him." }
    ] },
  { n:2, summary:"A man appears with a measuring line in his hand, going to measure Jerusalem's length and breadth — but an angel stops him with better news: the city will be inhabited like unwalled towns, so full of men and cattle that no wall can hold it, because the Lord Himself will be a wall of fire round about her and the glory in the midst of her. The vision becomes a call: flee from the land of the north, deliver yourself, O Zion, that dwellest with the daughter of Babylon, for the Lord has scattered His people like the four winds and now gathers them. Whoever touches them touches the apple of His eye, and their spoilers will become a spoil to their own servants. The chapter ends in song: sing and rejoice, O daughter of Zion, for the Lord comes to dwell in her midst; many nations will join to Him, Judah is His portion in the holy land, and all flesh is hushed before Him.",
    context:"A vision for the small, partly rebuilt Jerusalem of the return, promising a city too large for walls under the Lord's own protection and calling exiles out of Babylon.",
    keyVerses:[
      { ref:"Zechariah 2:5", text:"For I, saith the LORD, will be unto her a wall of fire round about, and will be the glory in the midst of her." },
      { ref:"Zechariah 2:8", text:"For thus saith the LORD of hosts; After the glory hath he sent me unto the nations which spoiled you: for he that toucheth you toucheth the apple of his eye." },
      { ref:"Zechariah 2:10", text:"Sing and rejoice, O daughter of Zion: for, lo, I come, and I will dwell in the midst of thee, saith the LORD." }
    ],
    takeaway:"God's presence outbuilds any wall: a people He surrounds with fire and fills with glory needs no other defense.",
    quiz:[
      { q:"What did the man in the third vision carry?", choices:["A pair of scales","A measuring line","A sharp sickle","A writer's inkhorn"], a:1, why:"Zechariah lifted his eyes and saw a man with a measuring line in his hand, going to measure Jerusalem's breadth and length." },
      { q:"Why would Jerusalem not need walls?", choices:["Enemies would fear to approach","The Persian empire would guard it","The Lord Himself would be a wall of fire and the glory in her midst","The city would be rebuilt on a mountaintop"], a:2, why:"Because of the multitude of men and cattle the city would be as towns without walls, with the Lord as a wall of fire round about and glory within." },
      { q:"What does he that toucheth you toucheth the apple of his eye teach?", choices:["God's people should avoid eye contact with enemies","Zion's walls protect the eye of the city","Punishment always falls on Jerusalem first","Harming God's people is touching what is most precious and guarded to Him"], a:3, why:"The Lord says He will shake His hand on the nations that spoiled them, and they will become a spoil to their own servants." }
    ] },
  { n:3, summary:"Joshua the high priest stands before the angel of the Lord with Satan at his right hand to resist him — and Joshua is clothed with filthy garments. The Lord rebukes Satan, asking whether this is not a brand plucked out of the fire, then commands that the filthy garments be taken away: behold, I have caused thine iniquity to pass from thee, and I will clothe thee with change of raiment. Zechariah himself asks that the fair mitre be set on Joshua's head, completing the priestly clothing. The angel then charges Joshua: if he walks in God's ways and keeps His charge, he will judge God's house and keep its courts. The vision opens outward: Joshua and his fellows are men wondered at, signs of the Lord's servant the BRANCH; the stone laid before Joshua bears seven eyes, and its engraving removes the iniquity of the land in one day, until every man calls his neighbor under the vine and fig tree.",
    context:"A vision given while Joshua the high priest served the returned exiles, portraying the cleansing of a guilty priesthood that stood in for a guilty people.",
    keyVerses:[
      { ref:"Zechariah 3:4", text:"And he answered and spake unto those that stood before him, saying, Take away the filthy garments from him. And unto him he said, Behold, I have caused thine iniquity to pass from thee, and I will clothe thee with change of raiment." },
      { ref:"Zechariah 3:7", text:"Thus saith the LORD of hosts; If thou wilt walk in my ways, and if thou wilt keep my charge, then thou shalt also judge my house, and shalt also keep my courts, and I will give thee places to walk among these that stand by." },
      { ref:"Zechariah 3:9", text:"For behold the stone that I have laid before Joshua; upon one stone shall be seven eyes: behold, I will engrave the graving thereof, saith the LORD of hosts, and I will remove the iniquity of that land in one day." }
    ],
    takeaway:"God answers the accuser by changing the accused: guilt removed, clean garments given, and service entrusted in their place.",
    quiz:[
      { q:"Who stood at Joshua's right hand in the vision?", choices:["Satan, to resist him","The prophet Haggai","The governor Zerubbabel","An angel holding a crown"], a:0, why:"Joshua stood before the angel of the Lord, and Satan stood at his right hand to resist him." },
      { q:"What did the change of raiment signify?", choices:["Joshua's promotion to governor","His iniquity passing from him","A new set of temple duties","The end of the priesthood"], a:1, why:"As the filthy garments were taken away the Lord said, I have caused thine iniquity to pass from thee, and I will clothe thee with change of raiment." },
      { q:"What does the phrase a brand plucked out of the fire teach about those God cleanses?", choices:["They escaped judgment by their own strength","Fire is a symbol of priesthood power","God rescues them from destruction they had already earned","Only priests can be delivered from danger"], a:2, why:"Joshua deserved burning, yet the Lord pulled him from it and rebuked his accuser — rescue and cleansing are God's gift before any calling." }
    ] },
  { n:4, summary:"The angel wakes Zechariah like a man roused from sleep and asks what he sees: a golden candlestick with a bowl on top, seven lamps fed by seven pipes, and two olive trees, one on each side. When Zechariah cannot interpret it, the angel gives the word of the Lord to Zerubbabel: not by might, nor by power, but by my spirit, saith the LORD of hosts. No great mountain can stand before Zerubbabel; it becomes a plain as he brings forth the headstone with shoutings of grace, grace unto it. The hands that laid the foundation will finish the house. Who despises the day of small things? Those who see the plummet in Zerubbabel's hand will rejoice, with the seven that are the eyes of the Lord running to and fro through the whole earth. Asked again about the olive trees, the angel answers: they are the two anointed ones that stand by the Lord of the whole earth.",
    context:"A vision sent to strengthen Zerubbabel's rebuilding crew, whose temple work under Persian permission looked small beside the memory of Solomon's house.",
    keyVerses:[
      { ref:"Zechariah 4:6", text:"Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts." },
      { ref:"Zechariah 4:9", text:"The hands of Zerubbabel have laid the foundation of this house; his hands shall also finish it; and thou shalt know that the LORD of hosts hath sent me unto you." },
      { ref:"Zechariah 4:10", text:"For who hath despised the day of small things? for they shall rejoice, and shall see the plummet in the hand of Zerubbabel with those seven; they are the eyes of the LORD, which run to and fro through the whole earth." }
    ],
    takeaway:"God's work runs on His Spirit, not human force — so small beginnings and slow tools deserve no contempt.",
    quiz:[
      { q:"What fed the candlestick's seven lamps in the vision?", choices:["Priests refilling them by hand","Flames kindled from the altar","Rain gathered in the bowl","Two olive trees, one on each side"], a:3, why:"The candlestick had a bowl with seven lamps, and two olive trees stood beside it, one on the right side and one on the left." },
      { q:"What did not by might, nor by power, but by my spirit mean for Zerubbabel's task?", choices:["The temple would be finished by God's Spirit, not armies or human strength","Zerubbabel needed more soldiers to guard the site","The work should stop until oil arrived","Only the priests could touch the building"], a:0, why:"The word to Zerubbabel tied the vision's never-failing oil to God's Spirit accomplishing what human force could not — finishing the house." },
      { q:"What question does the vision answer about the day of small things?", choices:["Why the foundation needed a second laying","Why no one should despise small beginnings","How to measure a mountain's height","When the seven lamps were first lit"], a:1, why:"For who hath despised the day of small things? — those watching Zerubbabel with the plummet would rejoice, for the Lord's eyes run through all the earth." }
    ] },
  { n:5, summary:"Two visions deal with sin in the land. First, a flying roll — a scroll twenty cubits long and ten wide — is the curse going over the face of the whole earth: it cuts off every thief on one side and every one that sweareth falsely by the Lord's name on the other, and it enters the guilty house to consume its timber and stones. Then an ephah, a measuring basket, goes forth, called their resemblance through all the earth. A talent of lead is lifted, and inside sits a woman whom the angel names Wickedness; he pushes her back into the basket and casts the weight of lead on its mouth. Two women with wings like a stork's carry the ephah between earth and heaven, and when Zechariah asks where it goes, the answer is the land of Shinar: a house will be built for it there, and it will be set on its own base.",
    context:"A vision confronting theft and false oaths in the restored community, with wickedness itself carted out of Judah to Shinar, the plain of ancient Babylon.",
    keyVerses:[
      { ref:"Zechariah 5:3", text:"Then said he unto me, This is the curse that goeth forth over the face of the whole earth: for every one that stealeth shall be cut off as on this side according to it; and every one that sweareth shall be cut off as on that side according to it." },
      { ref:"Zechariah 5:4", text:"I will bring it forth, saith the LORD of hosts, and it shall enter into the house of the thief, and into the house of him that sweareth falsely by my name: and it shall remain in the midst of his house, and shall consume it with the timber thereof and the stones thereof." },
      { ref:"Zechariah 5:8", text:"And he said, This is wickedness. And he cast it into the midst of the ephah; and he cast the weight of lead upon the mouth thereof." }
    ],
    takeaway:"God sees the sins hidden inside respectable houses; He judges them and carries wickedness out of His land.",
    quiz:[
      { q:"Which two sins did the flying roll single out?", choices:["Idolatry and Sabbath breaking","Lying to prophets and kings","Stealing and swearing falsely by God's name","Covetousness and drunkenness"], a:2, why:"The curse cut off every one that stealeth on one side and every one that sweareth falsely by the Lord's name on the other." },
      { q:"What did the angel name the woman sitting in the ephah?", choices:["Babylon","Jerusalem","Mercy","Wickedness"], a:3, why:"He said, This is wickedness, cast her into the ephah, and shut the weight of lead on its mouth." },
      { q:"Where were the women with stork's wings taking the ephah?", choices:["To the land of Shinar, to build it a house there","To the temple treasury","Back to the mountains of brass","Into the wilderness for forty years"], a:0, why:"The angel said they bore it to the land of Shinar, where it would be established and set upon her own base." }
    ] },
  { n:6, summary:"Four chariots come out from between two mountains of brass, drawn by red, black, white, and grisled-and-bay horses. The angel names them the four spirits of the heavens, which go forth from standing before the Lord of all the earth: black toward the north country, white after them, grisled toward the south, bays patrolling the whole earth — and the Lord's spirit is quieted by those that went north. The visions then become an enacted sign. Zechariah takes silver and gold from men of the captivity and makes crowns for Joshua the high priest, while the Lord speaks of the man whose name is The BRANCH: he shall build the temple of the Lord, bear the glory, and sit and rule on his throne — a priest upon his throne — with counsel of peace between them both. The crowns remain a memorial in the temple, and those that are far off will come and build if they diligently obey the Lord's voice.",
    context:"The closing vision of the Darius-era night series, joined to a crown-laying on Joshua the high priest among the returned exiles from Babylon.",
    keyVerses:[
      { ref:"Zechariah 6:5", text:"And the angel answered and said unto me, These are the four spirits of the heavens, which go forth from standing before the Lord of all the earth." },
      { ref:"Zechariah 6:13", text:"Even he shall build the temple of the LORD; and he shall bear the glory, and shall sit and rule upon his throne; and he shall be a priest upon his throne: and the counsel of peace shall be between them both." },
      { ref:"Zechariah 6:15", text:"And they that are far off shall come and build in the temple of the LORD, and ye shall know that the LORD of hosts hath sent me unto you. And this shall come to pass, if ye will diligently obey the voice of the LORD your God." }
    ],
    takeaway:"The Lord of all the earth sends out His spirit over the nations and crowns the hope of a priest-king who builds in peace.",
    quiz:[
      { q:"What material were the two mountains in the vision made of?", choices:["Granite","Brass","Gold","Marble"], a:1, why:"The four chariots came out from between two mountains, and the mountains were mountains of brass." },
      { q:"What did crowning Joshua the high priest point to?", choices:["Joshua replacing Zerubbabel as governor","A renewal of the Mosaic sacrifices","The BRANCH, who would build the temple and be a priest upon his throne","The end of the Persian occupation"], a:2, why:"The crowning came with the word about the man whose name is The BRANCH, who builds the temple, bears the glory, and unites priest and ruler in counsel of peace." },
      { q:"What did the four sets of chariot horses do?", choices:["Guarded the temple gates","Raced each other to Jerusalem","Carried the crowns to Babylon","Went forth to walk to and fro through the earth, quieting the Lord's spirit in the north"], a:3, why:"They were the four spirits of the heavens going out from before the Lord of all the earth; those toward the north country quieted His spirit." }
    ] },
  { n:7, summary:"Two years into the rebuild, messengers named Sherezer and Regem-melech send priests and prophets a question: should they keep weeping and fasting in the fifth month, as they have done for so many years? The Lord's answer turns the question back on them: through those seventy years of fasting in the fifth and seventh months, did you fast unto me, even to me? And when you ate and drank, was it not for yourselves? He points to what the former prophets cried while Jerusalem still prospered: execute true judgment, show mercy and compassions every man to his brother, oppress not the widow, the fatherless, the stranger, or the poor, and imagine no evil against a brother in your heart. Their fathers refused to hear, pulled away the shoulder, stopped their ears, and made their hearts as adamant stone — so great wrath came: as they would not hear God's cry, He would not hear theirs, and a whirlwind scattered them from the pleasant land they laid desolate.",
    context:"Asked in the fourth year of Darius, in Chisleu, about two years into the temple work, when a delegation wanted to know if the fasts mourning Jerusalem's fall should continue.",
    keyVerses:[
      { ref:"Zechariah 7:5", text:"Speak unto all the people of the land, and to the priests, saying, When ye fasted and mourned in the fifth and seventh month, even those seventy years, did ye at all fast unto me, even to me?" },
      { ref:"Zechariah 7:9", text:"Thus speaketh the LORD of hosts, saying, Execute true judgment, and shew mercy and compassions every man to his brother:" },
      { ref:"Zechariah 7:13", text:"Therefore it is come to pass, that as he cried, and they would not hear; so they cried, and I would not hear, saith the LORD of hosts:" }
    ],
    takeaway:"Fasts and forms mean nothing without a listening heart: God asks for justice, mercy, and obedience to His voice.",
    quiz:[
      { q:"What practice did the messengers ask whether to continue?", choices:["Weeping and fasting in the fifth month","Trading in the city gates","Bringing tithes of corn and wine","Reading the law aloud publicly"], a:0, why:"Sherezer and Regem-melech's men asked the priests and prophets, Should I weep in the fifth month, separating myself, as I have done these so many years?" },
      { q:"What flaw did the Lord expose in their seventy years of fasts?", choices:["They fasted on the wrong days","They were not fasting unto Him at all","They invited the nations to join","They ended the fasts too early"], a:1, why:"He asked, When ye fasted and mourned... did ye at all fast unto me, even to me? — and noted their eating and drinking were likewise for themselves." },
      { q:"What happened when the fathers stopped their ears against the former prophets?", choices:["They prospered quietly in the land","The prophets withdrew to Babylon","They cried in trouble and the Lord would not hear","God sent them more fasts to keep"], a:2, why:"Because they made their hearts as adamant stone, the Lord scattered them with a whirlwind; as he cried and they would not hear, so they cried and He would not hear." }
    ] },
  { n:8, summary:"The Lord promises Zion restored: He has returned to dwell in Jerusalem, a city of truth on the holy mountain, where old men and women sit in the streets and boys and girls play. If such things seem marvelous to the small remnant, they are not marvelous to God, who saves His people from east and west and is their God in truth and righteousness. Instead of no hire for man or beast and every man against his neighbor, the seed prospers, the vine fruits, heaven gives dew, and a curse becomes a blessing. The charge follows: speak truth, execute judgment of truth and peace in the gates, imagine no evil, and love no false oath — things the Lord hates. Then the direct answer: the fasts of the fourth, fifth, seventh, and tenth months become joy, gladness, and cheerful feasts, until many nations come to seek the Lord in Jerusalem and ten men take hold of a Jew's skirt, saying, We will go with you: for we have heard that God is with you.",
    context:"Given as the Lord's fuller answer about fasting while the temple still rose under Darius, promising Jerusalem's renewal and the gathering of the nations to seek Him.",
    keyVerses:[
      { ref:"Zechariah 8:3", text:"Thus saith the LORD; I am returned unto Zion, and will dwell in the midst of Jerusalem: and Jerusalem shall be called a city of truth; and the mountain of the LORD of hosts the holy mountain." },
      { ref:"Zechariah 8:19", text:"Thus saith the LORD of hosts; The fast of the fourth month, and the fast of the fifth, and the fast of the seventh, and the fast of the tenth, shall be to the house of Judah joy and gladness, and cheerful feasts; therefore love the truth and peace." },
      { ref:"Zechariah 8:23", text:"Thus saith the LORD of hosts; In those days it shall come to pass, that ten men shall take hold out of all languages of the nations, even shall take hold of the skirt of him that is a Jew, saying, We will go with you: for we have heard that God is with you." }
    ],
    takeaway:"When the Lord dwells among His people, mourning turns to feasting and the nations come looking for the God they see with you.",
    quiz:[
      { q:"In the promised Jerusalem, who does the Lord say will play in the streets?", choices:["Returning soldiers","Temple musicians","Priestly students","Boys and girls"], a:3, why:"The streets of the city shall be full of boys and girls playing in the streets thereof, while the aged sit safely nearby." },
      { q:"What did the Lord say the four annual fasts would become?", choices:["Joy, gladness, and cheerful feasts","Days of national assembly","Required temple pilgrimages","Days of silence and mourning"], a:0, why:"The fasts of the fourth, fifth, seventh, and tenth months were to become to the house of Judah joy and gladness and cheerful feasts — with the charge to love truth and peace." },
      { q:"According to the closing promise, what draws the nations to Jerusalem?", choices:["The beauty of its rebuilt walls","Hearing that God is with His people","Fear of judgment and drought","Wealth gathered from all the heathen"], a:1, why:"Ten men of all languages of the nations take hold of a Jew's skirt saying, We will go with you: for we have heard that God is with you." }
    ] },
  { n:9, summary:"A burden rolls through the lands north and along the coast: Hadrach, Damascus, and Hamath hear the word, and Tyre — that heaped silver as the dust and gold as the mire of her streets behind a strong hold — is cast out, her power smitten in the sea, devoured with fire. The Philistine cities fear and sorrow, yet a remnant among them turns to God like a governor in Judah. Then the promise turns to Zion: the Lord encamps about His house so no oppressor passes through, and Jerusalem must rejoice greatly — behold, thy King cometh unto thee: just, and having salvation; lowly, and riding upon an ass, and upon a colt the foal of an ass. Chariots, horses, and the battle bow are cut off; He speaks peace unto the heathen, and his dominion is from sea even to sea. By the blood of the covenant, prisoners leave the waterless pit as prisoners of hope; the Lord saves them as His flock, and corn and new wine cheer the young.",
    context:"An oracle against Syria, Tyre, and the Philistine cities held beside Zion's promise of a humble King while the restored community lived among those powers.",
    keyVerses:[
      { ref:"Zechariah 9:9", text:"Rejoice greatly, O daughter of Zion; shout, O daughter of Jerusalem: behold, thy King cometh unto thee: he is just, and having salvation; lowly, and riding upon an ass, and upon a colt the foal of an ass." },
      { ref:"Zechariah 9:10", text:"And I will cut off the chariot from Ephraim, and the horse from Jerusalem, and the battle bow shall be cut off: and he shall speak peace unto the heathen: and his dominion shall be from sea even to sea, and from the river even to the ends of the earth." },
      { ref:"Zechariah 9:16", text:"And the LORD their God shall save them in that day as the flock of his people: for they shall be as the stones of a crown, lifted up as an ensign upon his land." }
    ],
    takeaway:"The King God sends is lowly, riding on an ass: His peace is won without war horses and reaches sea to sea.",
    quiz:[
      { q:"How does the promised King enter Jerusalem?", choices:["In a chariot with the battle bow","On a white horse with armies","Lowly, riding upon an ass","By ship through the sea"], a:2, why:"Daughter Zion is told to rejoice greatly: behold, thy King cometh — just and having salvation, lowly, riding on an ass and a colt the foal of an ass." },
      { q:"What wealthy coastal city does the Lord cast out, its power smitten in the sea?", choices:["Damascus","Hamath","Hadrach","Tyrus"], a:3, why:"Tyrus built herself a strong hold and heaped up silver as the dust, but the Lord smote her power in the sea and she was devoured with fire." },
      { q:"What happens to weapons under this King's reign?", choices:["Chariots, horses, and the battle bow are cut off as He speaks peace to the heathen","Every soldier receives a stronger bow","They are stored in the temple vaults","The nations arm Jerusalem for defense"], a:0, why:"The chariot is cut off from Ephraim, the horse from Jerusalem, and the battle bow, while His dominion stretches from sea to sea." }
    ] },
  { n:10, summary:"Ask rain of the Lord in the time of the latter rain, for idols speak vanity, diviners see lies, and false dreams comfort in vain — the people wandered like a troubled flock with no shepherd. The Lord's anger burned against the shepherds and the goats, but He visits His flock, the house of Judah, making them as His goodly horse in battle; out of them come the corner, the nail, the battle bow, and the ruler, and they fight because the Lord is with them. He strengthens Judah and saves the house of Joseph, restoring them as though He had never cast them off, till Ephraim's heart rejoices as through wine. He hisses for His redeemed, sows them among the peoples, and gathers them out of Egypt and Assyria into Gilead and Lebanon until no room is left; Assyria's pride falls, Egypt's scepter departs, and they walk up and down in His name.",
    context:"A restoration promise addressed to both Judah and Joseph — the scattered houses of Israel — naming Egypt and Assyria as the lands from which the gathering reverses the exile.",
    keyVerses:[
      { ref:"Zechariah 10:1", text:"Ask ye of the LORD rain in the time of the latter rain; so the LORD shall make bright clouds, and give them showers of rain, to every one grass in the field." },
      { ref:"Zechariah 10:6", text:"And I will strengthen the house of Judah, and I will save the house of Joseph, and I will bring them again to place them; for I have mercy upon them: and they shall be as though I had not cast them off: for I am the LORD their God, and will hear them." },
      { ref:"Zechariah 10:12", text:"And I will strengthen them in the LORD; and they shall walk up and down in his name, saith the LORD." }
    ],
    takeaway:"The Lord is His flock's true shepherd: He gathers the redeemed from every scattering and lets them walk in His name.",
    quiz:[
      { q:"What does the Lord tell the people to ask Him for, and when?", choices:["Mercy, in the seventh month","Rain, in the time of the latter rain","Crowns, at the feast","Forgiveness, on fast days"], a:1, why:"Ask ye of the LORD rain in the time of the latter rain — idols and diviners only spoke vanity and comforted in vain." },
      { q:"Why were the people once like a flock that was troubled?", choices:["Famine had emptied their barns","Their cities had no walls","There was no shepherd, and idols and diviners gave them lies","Egypt and Assyria had closed their borders"], a:2, why:"The idols spoke vanity, the diviners saw a lie, and the false dreams comforted in vain — so they went their way troubled, because there was no shepherd." },
      { q:"What does the promise that they shall be as though I had not cast them off reveal about God's restoration?", choices:["Restoration depends on perfect record-keeping","Scattering permanently cancels covenant blessing","Only Judah, not Joseph, is ever restored","God's mercy reverses exile so completely it is as if it never happened"], a:3, why:"He strengthens Judah, saves Joseph, and brings them again to place them, for He has mercy on them as their God who hears them." }
    ] },
  { n:11, summary:"A howl runs through Lebanon's cedars, Bashan's oaks, and the shepherds whose glory is spoiled. The Lord commands the prophet to feed the flock of the slaughter — sheep whose possessors kill them without guilt and whose own shepherds pity them not — and Zechariah enacts the role with two staves, one named Beauty, the other Bands. He cuts off three shepherds in one month, then renounces the flock: that that dieth, let it die. Cutting the staff Beauty breaks the covenant with all the people; when he asks his price, they weigh thirty pieces of silver, which the Lord directs him to cast to the potter in the house of the Lord. Cutting the second staff, Bands, breaks the brotherhood between Judah and Israel. A foolish, idol shepherd then rises who does not seek the cut off, heal the broken, or feed the standing, and a woe falls on him — sword on his arm and right eye, the arm dried up, the eye darkened.",
    context:"A prophetic sign-act in which Zechariah shepherds the flock of slaughter, dramatizing how the nation's leaders valued the Lord's care and let it be broken.",
    keyVerses:[
      { ref:"Zechariah 11:7", text:"And I will feed the flock of slaughter, even you, O poor of the flock. And I took unto me two staves; the one I called Beauty, and the other I called Bands; and I fed the flock." },
      { ref:"Zechariah 11:12", text:"And I said unto them, If ye think good, give me my price; and if not, forbear. So they weighed for my price thirty pieces of silver." },
      { ref:"Zechariah 11:13", text:"And the LORD said unto me, Cast it unto the potter: a goodly price that I was prised at of them. And I took the thirty pieces of silver, and cast them to the potter in the house of the LORD." }
    ],
    takeaway:"What a people pays its shepherd shows what it thinks of God — and the Lord does not overlook false shepherds.",
    quiz:[
      { q:"What were the prophet's two staves named?", choices:["Beauty and Bands","Mercy and Judgment","Truth and Peace","Zion and Babylon"], a:0, why:"He took two staves, calling one Beauty and the other Bands, and fed the flock with them." },
      { q:"What did cutting the staff Beauty signify?", choices:["The end of the temple sacrifices","Breaking the covenant made with all the people","The loss of the harvest","The closing of the city gates"], a:1, why:"He cut Beauty asunder that he might break his covenant which he had made with all the people, and the poor of the flock knew it was the word of the Lord." },
      { q:"What price did the flock give their shepherd, and where did it go?", choices:["Fifty shekels of gold, kept for the temple","A measure of fine flour, given to the poor","Thirty pieces of silver, cast to the potter in the house of the LORD","A crown of silver, set on Joshua's head"], a:2, why:"They weighed thirty pieces of silver, and at the Lord's word the prophet cast it to the potter in the house of the LORD — a goodly price at which he was valued." }
    ] },
  { n:12, summary:"The burden for Israel comes from the Lord who stretches forth the heavens, lays the earth's foundation, and forms the spirit of man within him. In the last siege Jerusalem becomes a cup of trembling to the peoples round about and a burdensome stone for all people: all who burden themselves with it are cut in pieces, though all the nations gather, for the Lord smites every horse with astonishment and its rider with madness while His eyes open on Judah. Judah's governors are a hearth of fire among wood and a torch in a sheaf, yet the Lord saves the tents of Judah first so the glory of David's house cannot magnify itself against them; the feeble will be as David, and David's house as the angel of the LORD before them. Then the Lord pours out the spirit of grace and of supplications, and they look upon Him whom they have pierced, mourning as for an only son, every family apart, as at Hadadrimmon in the valley of Megiddon.",
    context:"An oracle of the final siege and deliverance of Jerusalem, in which the Lord Himself defends the city and pours out a mourning over the pierced One on every family.",
    keyVerses:[
      { ref:"Zechariah 12:3", text:"And in that day will I make Jerusalem a burdensome stone for all people: all that burden themselves with it shall be cut in pieces, though all the people of the earth be gathered together against it." },
      { ref:"Zechariah 12:10", text:"And I will pour upon the house of David, and upon the inhabitants of Jerusalem, the spirit of grace and of supplications: and they shall look upon me whom they have pierced, and they shall mourn for him, as one mourneth for his only son, and shall be in bitterness for him, as one that is in bitterness for his firstborn." },
      { ref:"Zechariah 12:8", text:"In that day shall the LORD defend the inhabitants of Jerusalem; and he that is feeble among them at that day shall be as David; and the house of David shall be as God, as the angel of the LORD before them." }
    ],
    takeaway:"God defends the impossible siege and breaks the hardest heart: grace pours out wherever the pierced One is truly seen.",
    quiz:[
      { q:"What two things does the Lord make Jerusalem to the nations in that day?", choices:["A refuge and a fortress","A mirror and a lamp","A lampstand and a crown","A cup of trembling and a burdensome stone"], a:3, why:"Jerusalem becomes a cup of trembling to all the people round about and a burdensome stone; all that burden themselves with it are cut in pieces." },
      { q:"Why does the Lord save the tents of Judah first?", choices:["So the glory of David's house will not magnify itself against Judah","Because Judah's army is the largest","So the siege will end more quickly","Because Jerusalem's gates are closed"], a:0, why:"The text says the tents of Judah are saved first, that the glory of the house of David and of Jerusalem's inhabitants do not magnify themselves against Judah." },
      { q:"What does the Lord pour out before the people look on Him whom they have pierced?", choices:["Rain on the harvested fields","The spirit of grace and of supplications","A great tumult among the governors","Plague on the enemy horses"], a:1, why:"The pouring of the spirit of grace and supplications leads to looking on the pierced One and mourning as for an only son." }
    ] },
  { n:13, summary:"The mourning of the last chapter opens into cleansing: in that day a fountain is opened to the house of David and the inhabitants of Jerusalem for sin and for uncleanness. The Lord cuts off the names of the idols out of the land and causes the prophets and the unclean spirit to pass out; a father and mother will thrust through a son who prophesies lies, and false prophets, ashamed of their visions, will deny being prophets and explain the wounds on their hands as wounds from the house of their friends. Then the sword wakes against the Lord's shepherd, the man that is His fellow: smite the shepherd, and the sheep shall be scattered, and the Lord turns His hand upon the little ones. Two parts in the land are cut off and die, but the third is brought through the fire, refined as silver and tried as gold, until He says, It is my people, and they answer, The LORD is my God.",
    context:"A continuation of the same in-that-day promise, pairing cleansing from sin and uncleanness with the smiting of the shepherd and a refined third-part remnant.",
    keyVerses:[
      { ref:"Zechariah 13:1", text:"In that day there shall be a fountain opened to the house of David and to the inhabitants of Jerusalem for sin and for uncleanness." },
      { ref:"Zechariah 13:7", text:"Awake, O sword, against my shepherd, and against the man that is my fellow, saith the LORD of hosts: smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones." },
      { ref:"Zechariah 13:9", text:"And I will bring the third part through the fire, and will refine them as silver is refined, and will try them as gold is tried: they shall call on my name, and I will hear them: I will say, It is my people: and they shall say, The LORD is my God." }
    ],
    takeaway:"Cleansing comes dear: the fountain for sin opens as the shepherd is smitten, and fire refines a people who call God their own.",
    quiz:[
      { q:"What is the fountain of Zechariah 13:1 opened for?", choices:["Watering the flocks in drought","Washing the temple's brass altar","Sin and uncleanness for the house of David and Jerusalem","Filling Jerusalem's new reservoir"], a:2, why:"In that day a fountain is opened to the house of David and the inhabitants of Jerusalem for sin and for uncleanness." },
      { q:"What happens when the sword smites the shepherd?", choices:["The flock is gathered into the fold","The mountains of brass shake","The idols return to the land","The sheep are scattered"], a:3, why:"Awake, O sword, against my shepherd... smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones." },
      { q:"What does the refining fire do to the surviving third part?", choices:["Purifies them as silver and gold until they call on the Lord's name and He claims them","Drives them out to Egypt and Assyria","Teaches them to prophesy again","Separates Judah from Israel permanently"], a:0, why:"The Lord brings the third part through the fire, refined as silver, tried as gold; they call on His name, and the covenant is spoken from both sides." }
    ] },
  { n:14, summary:"The day of the LORD opens with Jerusalem's darkest hour: all nations gather, the city is taken, and half its people go captive. Then the LORD goes forth — His feet stand on the mount of Olives, which cleaves east and west into a great valley, and the people flee as in Uzziah's earthquake while the LORD comes with all His saints. That day is like none other: not day nor night, yet at evening time it shall be light, and living waters flow from Jerusalem, half toward the former sea and half toward the hinder. The LORD becomes king over all the earth, one LORD, His name one; Jerusalem is lifted up and safely inhabited, while a plague consumes the enemy and their hands turn on their neighbors. Survivors go up yearly to worship the King and keep the feast of tabernacles, or no rain falls on them, and even the horses' bells and the common pots are marked HOLINESS UNTO THE LORD, till no Canaanite remains in the house of the LORD of hosts.",
    context:"The closing oracle of the Lord's day: a gathered siege against Jerusalem ends in the mountain-splitting deliverance, the feast pilgrimage of the nations, and a city marked by holiness.",
    keyVerses:[
      { ref:"Zechariah 14:4", text:"And his feet shall stand in that day upon the mount of Olives, which is before Jerusalem on the east, and the mount of Olives shall cleave in the midst thereof toward the east and toward the west, and there shall be a very great valley; and half of the mountain shall remove toward the north, and half of it toward the south." },
      { ref:"Zechariah 14:9", text:"And the LORD shall be king over all the earth: in that day shall there be one LORD, and his name one." },
      { ref:"Zechariah 14:20", text:"In that day shall there be upon the bells of the horses, HOLINESS UNTO THE LORD; and the pots in the LORD's house shall be like the bowls before the altar." }
    ],
    takeaway:"The Lord's day ends the siege and spreads holiness to the common things of life under one King over all the earth.",
    quiz:[
      { q:"Which mountain splits in two when the LORD's feet stand on it?", choices:["Mount Sinai","The mount of Olives","Mount Zion","Mount Hor"], a:1, why:"His feet shall stand on the mount of Olives, which cleaves in the midst toward east and west, forming a very great valley for the people to flee through." },
      { q:"What happens to nations that refuse to go up to keep the feast of tabernacles?", choices:["They are destroyed immediately by fire","Their kings lose their crowns","No rain falls on them, and Egypt gets the plague","Their cities become desolate forever"], a:2, why:"Whoso will not come up to worship the King, the LORD of hosts, shall have no rain; Egypt, which has little rain, gets the plague instead." },
      { q:"What does HOLINESS UNTO THE LORD written on the horses' bells teach about that day?", choices:["Only priests may own horses","Animals replace sacrifices in worship","Jerusalem will trade horses with Egypt","Holiness reaches the most ordinary things of life"], a:3, why:"The bells of the horses, the pots in the Lord's house, and every pot in Jerusalem and Judah are holiness unto the LORD — the whole of daily life set apart." }
    ] }
);
(_ml.chapters = _ml.chapters || []).push(
  { n:1, summary:"Malachi's burden opens with God's declaration, I have loved you — and the people's chilly reply, Wherein hast thou loved us? The Lord points to twin brothers: He loved Jacob but laid Esau's mountains and heritage waste, and Edom's vow to rebuild will fail — they shall build, but I will throw down. The charge then turns on the priests: a son honors his father and a servant his master, so where is the honor and fear due His name? They despise it by offering polluted bread on the altar and sacrificing blind, lame, and sick animals they would never set before the governor. God has no pleasure in such worship, yet from the rising of the sun to its going down His name will be great among the Gentiles with pure offerings in every place — for He is a great King whose name is dreadful among the heathen.",
    context:"An undated dispute-style message to Israel — aimed first at the priests serving the altar — framed as the Lord answering the people's skeptical questions.",
    keyVerses:[
      { ref:"Malachi 1:2", text:"I have loved you, saith the LORD. Yet ye say, Wherein hast thou loved us?" },
      { ref:"Malachi 1:8", text:"And if ye offer the blind for sacrifice, is it not evil? and if ye offer the lame and sick, is it not evil? offer it now unto thy governor; will he be pleased with thee, or accept thy person? saith the LORD of hosts." },
      { ref:"Malachi 1:11", text:"For from the rising of the sun even unto the going down of the same my name shall be great among the Gentiles; and in every place incense shall be offered unto my name, and a pure offering: for my name shall be great among the heathen, saith the LORD of hosts." }
    ],
    takeaway:"A great King deserves the first and the whole, not the blind, lame, and sick leftovers of our flocks and budgets.",
    quiz:[
      { q:"What kinds of animals were the priests offering on the Lord's altar?", choices:["Blind, lame, and sick ones","Firstborn males without blemish","Only young lambs","Animals bought from Edom"], a:0, why:"They brought the torn, the lame, and the sick — offering the blind, the lame, and the sick that they would never have dared to give their governor." },
      { q:"Why does the Lord tell them to offer such sacrifices to their governor?", choices:["To fund the temple rebuilding","To shame them — they would never give a human ruler what they give God","Because the governor requested them","To prove the sacrifices were legal"], a:1, why:"Offer it now unto thy governor; will he be pleased with thee? — if a human ruler would reject such gifts, how much more the great King." },
      { q:"What does the Lord's claim to be a great King teach about acceptable worship?", choices:["Worship is judged by its cost to the worshiper, not its quality","Any offering is fine if the heart is warm","God deserves our best, and cheap worship dishonors His name","Only Gentiles may offer pure offerings"], a:2, why:"Cursed is the deceiver who vows a male in his flock and sacrifices a corrupt thing, for the Lord is a great King and His name is dreadful among the heathen." }
    ] },
  { n:2, summary:"The commandment addresses the priests: if they will not give glory to God's name, the curse is already on their blessings, and dung from their own feasts will be spread on their faces. The Lord recalls His covenant with Levi — life and peace for Levi's reverent fear, the law of truth in his mouth, many turned from iniquity — and accuses the priests of departing from the way, causing many to stumble, and corrupting that covenant, so He makes them contemptible before the people. The charge widens: Judah has profaned the holiness of the Lord by marrying the daughter of a strange god, and men cover the altar with tears while dealing treacherously with the wife of their youth, the companion and wife of their covenant, made one with them that God might seek a godly seed. The Lord hates putting away, and the people weary Him by calling evildoers good and asking, Where is the God of judgment?",
    context:"Still the Lord's dispute with the priests and people of the restored community, tying failed worship to failed covenant loyalty toward brother, God, and wife.",
    keyVerses:[
      { ref:"Malachi 2:5", text:"My covenant was with him of life and peace; and I gave them to him for the fear wherewith he feared me, and was afraid before my name." },
      { ref:"Malachi 2:7", text:"For the priest's lips should keep knowledge, and they should seek the law at his mouth: for he is the messenger of the LORD of hosts." },
      { ref:"Malachi 2:14", text:"Yet ye say, Wherefore? Because the LORD hath been witness between thee and the wife of thy youth, against whom thou hast dealt treacherously: yet is she thy companion, and the wife of thy covenant." }
    ],
    takeaway:"God witnesses every covenant: reverent teaching, honest brotherhood, and faithfulness to the wife of thy youth are one loyalty.",
    quiz:[
      { q:"Whose covenant had the priests corrupted?", choices:["Abraham's","Moses'","David's","Levi's"], a:3, why:"The Lord contrasts the covenant of life and peace He made with Levi, which the priests corrupted by departing from the way and causing many to stumble." },
      { q:"Why did the Lord no longer regard the offering brought with weeping and crying out?", choices:["Because the men had dealt treacherously against the wife of their youth","Because the altar had been defiled by strangers","Because the offerings were from Edom","Because the priests fasted in the wrong month"], a:0, why:"The Lord was witness between each man and the wife of his youth; treachery at home had covered the altar with tears He would not regard." },
      { q:"What does this chapter teach about how God views marriage covenants?", choices:["They are private matters beyond religion","He witnesses them and hates treachery against the wife of one's youth","They may be dissolved for temple service","They matter only when children are born"], a:1, why:"The Lord hath been witness between thee and the wife of thy youth; He hateth putting away and charges each man to take heed to his spirit." }
    ] },
  { n:3, summary:"A messenger comes first: the Lord sends one to prepare the way, and the Lord whom they seek will suddenly come to His temple as the messenger of the covenant. Who can abide the day of His coming? He is like a refiner's fire and fullers' soap, purifying the sons of Levi as gold and silver until offerings in righteousness make Judah's sacrifice pleasant as in former years. Then He comes near in judgment, a swift witness against sorcerers, adulterers, false swearers, and those who cheat the hireling, the widow, and the fatherless. Because the LORD changes not, the sons of Jacob are not consumed; yet robbed of tithes and offerings, the nation hears His challenge — will a man rob God? — and His invitation to prove Him and see the windows of heaven open and the devourer rebuked. Meanwhile those who feared the LORD speak often one to another; He hearkens and hears, a book of remembrance is written before Him, and in the day He makes up His jewels, they are His.",
    context:"The chapter answers a weary generation's complaints in the same undated dialogue, promising the Lord's sudden coming to His temple while calling for honest tithes among the restored community.",
    keyVerses:[
      { ref:"Malachi 3:1", text:"Behold, I will send my messenger, and he shall prepare the way before me: and the Lord, whom ye seek, shall suddenly come to his temple, even the messenger of the covenant, whom ye delight in: behold, he shall come, saith the LORD of hosts." },
      { ref:"Malachi 3:10", text:"Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it." },
      { ref:"Malachi 3:16", text:"Then they that feared the LORD spake often one to another: and the LORD hearkened, and heard it, and a book of remembrance was written before him for them that feared the LORD, and that thought upon his name." }
    ],
    takeaway:"Prove the Lord with whole consecration: He opens heaven's windows on the faithful and writes their names in His book of remembrance.",
    quiz:[
      { q:"What was written before the Lord for those who feared Him?", choices:["A new set of statutes","The names of the proud","A book of remembrance","A scroll of the law of Moses"], a:2, why:"The LORD hearkened and heard the faithful speaking often one to another, and a book of remembrance was written for them that feared the LORD and thought upon His name." },
      { q:"In what had the people robbed God?", choices:["In firstfruits and sacrifices","In sabbath observance","In vows and fasts","In tithes and offerings"], a:3, why:"Will a man rob God? Yet ye have robbed me, the Lord said — and the answer to Wherein? was, In tithes and offerings." },
      { q:"What did the Lord promise if they brought all the tithes into the storehouse?", choices:["Open windows of heaven and a blessing too big to receive","Immediate relief from Persian taxation","Rain only for the temple fields","A return of the ark of the covenant"], a:0, why:"Prove me now herewith, He said — He would open the windows of heaven, pour out a blessing without room enough, and rebuke the devourer." }
    ] },
  { n:4, summary:"The final chapter sets two destinies under one coming day. For the proud and all that do wickedly, the day burns as an oven: they become stubble, left neither root nor branch. For those who fear the Lord's name, the Sun of righteousness arises with healing in his wings, and they go forth and grow up as calves of the stall, treading the wicked to ashes underfoot. Between those futures stand a summons and a promise: remember the law of Moses with its statutes and judgments, commanded at Horeb for all Israel. And behold, the Lord will send Elijah the prophet before the great and dreadful day of the LORD, to turn the heart of the fathers to the children and the children's to the fathers, lest the earth be smitten with a curse. The Old Testament closes with the law remembered, a prophet promised, and hearts turned.",
    context:"The last chapter of the Old Testament closes the canon, pointing back to Moses at Horeb and forward to Elijah's coming before the Lord's great and dreadful day.",
    keyVerses:[
      { ref:"Malachi 4:2", text:"But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall." },
      { ref:"Malachi 4:5", text:"Behold, I will send you Elijah the prophet before the coming of the great and dreadful day of the LORD:" },
      { ref:"Malachi 4:6", text:"And he shall turn the heart of the fathers to the children, and the heart of the children to their fathers, lest I come and smite the earth with a curse." }
    ],
    takeaway:"For those who fear His name the coming day brings healing, not burning — and Elijah's work is to turn hearts before it arrives.",
    quiz:[
      { q:"Which prophet does the Lord promise to send before the great and dreadful day of the LORD?", choices:["Moses","Elijah","Isaiah","Malachi"], a:1, why:"Behold, I will send you Elijah the prophet before the coming of the great and dreadful day of the LORD." },
      { q:"What work is the promised prophet sent to do?", choices:["Rebuild the walls of Jerusalem","Restore animal sacrifice","Turn the hearts of fathers to children and children to fathers","Write a new book of remembrance"], a:2, why:"Elijah's mission is reconciliation within families, lest the Lord come and smite the earth with a curse." },
      { q:"How does the Sun of righteousness divide the same coming day for two kinds of people?", choices:["It hides from everyone equally","It burns both the wicked and the faithful","It postpones judgment indefinitely","It burns the wicked like an oven but rises with healing for those who fear God's name"], a:3, why:"The day leaves the proud neither root nor branch, but unto you that fear my name shall the Sun of righteousness arise with healing in his wings." }
    ] }
);
